import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const $=s=>document.querySelector(s), tr=(en,es)=>S.lang==='es'?es:en;
const saveKey='lastDawnSave';
let S={name:'Wayfarer',floor:1,level:1,xp:0,xpNext:90,hp:100,mp:60,shards:0,points:0,kills:0,stats:{Might:5,Vigor:5,Insight:5,Agility:5},difficulty:'normal',lang:'en',potions:3,weapon:null,armor:null,relics:[],quests:[],log:[],hasStarted:false};
let scene,camera,renderer,clock,player={x:0,z:5,yaw:0,pitch:0},keys={},enemies=[],npc=null,stairs=null,attackAt=0,powerAt=0,guardUntil=0,toastTimer,dialogNpc=null,moveTouch={x:0,y:0};
const rarities=['Common','Uncommon','Rare','Epic','Legendary'], rarityClass=r=>'rarity-'+r.toLowerCase();
const names=['Dawn splinter','Warden’s edge','Glass comet','Oath of the deep','Sun-eater','Mothwing charm','Keeper’s seal','Salt iron blade','Pilgrim’s mantle','Cinder heart'];
function init3d(){scene=new THREE.Scene();scene.background=new THREE.Color(0x101922);scene.fog=new THREE.FogExp2(0x101922,.026);camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.1,100);camera.rotation.order='YXZ';renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;$('#scene').appendChild(renderer.domElement);scene.add(new THREE.HemisphereLight(0x9ab8cd,0x211d25,1.7));const lamp=new THREE.PointLight(0xe4b879,55,26,2);lamp.position.set(0,5,0);lamp.castShadow=true;scene.add(lamp);buildFloor();clock=new THREE.Clock();animate();}
function mat(color,rough=.8,em=0){return new THREE.MeshStandardMaterial({color,roughness:rough,emissive:color,emissiveIntensity:em})}
function box(x,y,z,sx,sy,sz,m){let o=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;scene.add(o);return o}
function buildFloor(){if(!scene)return;for(const o of [...scene.children])if(o.userData.floorObj)scene.remove(o);const stone=mat(0x35434a),dark=mat(0x202c32),gold=mat(0x9b7545,.5,.18),glow=mat(0x54a89c,.35,.3);const add=o=>{o.userData.floorObj=true;return o};
add(box(0,-.25,0,20,.5,34,stone));add(box(0,7,-16,20,14,.6,dark));add(box(-10,7,0,.6,14,34,dark));add(box(10,7,0,.6,14,34,dark));add(box(0,13,0,20,.4,34,dark));
for(let z=-14;z<16;z+=7){for(const x of [-7,7]){let c=add(box(x,3.2,z,1.5,6.4,1.5,stone));add(box(x,6.5,z,1.8,.24,1.8,gold));}let orb=add(new THREE.Mesh(new THREE.SphereGeometry(.14,12,10),glow));orb.position.set(0,5.6,z);scene.add(orb);orb.userData.floorObj=true;}
for(let i=-8;i<=8;i+=2)add(box(i,.015,-.5,.035,.02,30,gold));
let plinth=add(box(0,.15,-13,4,.3,2,dark));stairs=add(new THREE.Group());for(let n=0;n<6;n++){let st=new THREE.Mesh(new THREE.BoxGeometry(3,.32,1.05),n===5?glow:stone);st.position.set(0,.2+n*.42,-12-n*.72);stairs.add(st);}stairs.position.y=.1;scene.add(stairs);stairs.userData.floorObj=true;
player.x=0;player.z=5;player.yaw=0;player.pitch=0;camera.position.set(player.x,1.68,player.z);camera.rotation.set(0,0,0);
const floorColor=new THREE.Color().setHSL((S.floor*0.061)%1,.3,.22);scene.background=floorColor;scene.fog.color=floorColor;
spawnFloorEntities();}
function clearEntities(){for(const e of enemies)scene.remove(e.mesh);enemies=[];if(npc){scene.remove(npc.mesh);npc=null;}$('#enemybar').style.display='none';$('#bossbar').style.display='none';}
function spawnFloorEntities(){clearEntities();let boss=S.floor%10===0||S.floor===100;let count=boss?1:Math.min(1+Math.floor(S.floor/8),4);for(let i=0;i<count;i++)spawnEnemy(boss,i);if(S.floor%5===0&&!boss)spawnNPC();}
function spawnEnemy(boss,i){let hue=boss?0x9e4f48:(0x667e86+Math.floor(Math.random()*0x222222));let mesh=new THREE.Group(),body=new THREE.Mesh(new THREE.CapsuleGeometry(boss?.8:.45,boss?1.5:.65,5,10),mat(hue,.6,.15));body.position.y=boss?1.3:1;mesh.add(body);let eye=new THREE.Mesh(new THREE.SphereGeometry(.12,8,6),mat(0xf1ba75,.2,1.3));eye.position.set(0,boss?2.3:1.55,-.37);mesh.add(eye);let ring=new THREE.Mesh(new THREE.TorusGeometry(boss?1:.6,.045,6,24),mat(boss?0xe29264:0x8bc4bb,.5,.5));ring.rotation.x=Math.PI/2;ring.position.y=.12;mesh.add(ring);mesh.position.set((i-(Math.ceil((S.floor%10===0||S.floor===100?1:Math.min(1+Math.floor(S.floor/8),4))-1)/2))*3,0,-5+Math.random()*2);scene.add(mesh);let max=(boss?140:38)+S.floor*(boss?14:4);if(S.difficulty==='story')max*=.72;if(S.difficulty==='hard')max*=1.35;enemies.push({mesh,hp:max,max,boss,name:boss?(S.floor===100?'THE LAST DAWN':'FLOOR '+S.floor+' · THE WARDEN'):['Hollow','Ashbound','Gloamling','Tower husk'][Math.floor(Math.random()*4)],attack:0,speed:.55+Math.random()*.25});}

