input.newString:
enemies.push({mesh,hp:max,max,boss,name:boss?(S.floor===100?'THE LAST DAWN':'FLOOR '+S.floor+' · THE WARDEN'):['Hollow','Ashbound','Gloamling','Tower husk'][Math.floor(Math.random()*4)],attack:0,speed:.55+Math.random()*.25});if(boss){$('#bossbar').style.display='block';$('#bossName').textContent=enemies[0].name;}}
function spawnNPC(){const labels=['Ilyra the Cartographer','Old Fen','Mira of the Quiet Bell','The Unlicensed Saint','Kestrel'];let mesh=new THREE.Group(),robe=new THREE.Mesh(new THREE.ConeGeometry(.55,1.5,8),mat(0x697d78,.9,.08));robe.position.y=.8;mesh.add(robe);let head=new THREE.Mesh(new THREE.SphereGeometry(.27,12,10),mat(0xc69c79));head.position.y=1.75;mesh.add(head);let light=new THREE.PointLight(0x77d9c4,8,7);light.position.y=2;mesh.add(light);mesh.position.set(3,0,-6);scene.add(mesh);npc={mesh,name:labels[(S.floor/5-1)%labels.length],mood:Math.random(),traded:false};}
function animate(){requestAnimationFrame(animate);if(!scene)return;let dt=Math.min(clock.getDelta(),.05);if(S.hasStarted)tick(dt);renderer.render(scene,camera);}
function tick(dt){if(!$('#welcome').classList.contains('open')&&!$('#panel').classList.contains('open')&&!$('#dialog').classList.contains('open')){const f=(keys.KeyW?1:0)-(keys.KeyS?1:0)-moveTouch.y,side=(keys.KeyD?1:0)-(keys.KeyA?1:0)+moveTouch.x;let len=Math.hypot(f,side)||1,speed=4.2*(keys.ShiftLeft?1.45:1);player.x+=((side/len)*Math.cos(player.yaw)+(f/len)*Math.sin(player.yaw))*speed*dt;player.z+=((-f/len)*Math.cos(player.yaw)+(side/len)*Math.sin(player.yaw))*speed*dt;player.x=Math.max(-8.6,Math.min(8.6,player.x));player.z=Math.max(-15,Math.min(15,player.z));camera.position.set(player.x,1.68,player.z);camera.rotation.set(player.pitch,player.yaw,0,'YXZ');}
for(const e of enemies){let dx=player.x-e.mesh.position.x,dz=player.z-e.mesh.position.z,d=Math.hypot(dx,dz);if(d>1.8&&d<14){e.mesh.position.x+=dx/d*e.speed*dt;e.mesh.position.z+=dz/d*e.speed*dt;}e.mesh.lookAt(player.x,1,player.z);if(d<2.1&&Date.now()>e.attack){e.attack=Date.now()+1500;let damage=(e.boss?14:7)+S.floor*.22;if(Date.now()>guardUntil)S.hp-=damage;else S.mp=Math.max(0,S.mp-5);sound('hurt');if(S.hp<=0)onDeath();updateUI();}if(e.boss){$('#bossFill').style.width=Math.max(0,100*e.hp/e.max)+'%';}else if(d<9){$('#enemybar').style.display='block';$('#enemyName').textContent=e.name;$('#enemyFill').style.width=Math.max(0,100*e.hp/e.max)+'%';}}
if(!enemies.some(e=>!e.boss&&Math.hypot(player.x-e.mesh.position.x,player.z-e.mesh.position.z)<9))$('#enemybar').style.display='none';if(npc&&Math.hypot(player.x-npc.mesh.position.x,player.z-npc.mesh.position.z)<2.7){$('#hint').textContent='E · SPEAK WITH '+npc.name.toUpperCase();}else if(enemies.length===0){$('#hint').textContent=S.floor<100?'THE WAY UP IS OPEN · WALK TO THE STAIR':'THE TOWER IS QUIET';}else{$('#hint').textContent='WASD MOVE · CLICK / SPACE ATTACK · Q / E POWERS';}if(enemies.length===0&&Math.hypot(player.x,player.z+13)<3&&S.floor<100)nextFloor();if(npc&&Math.hypot(player.x-npc.mesh.position.x,player.z-npc.mesh.position.z)<2.7&&keys.KeyE){keys.KeyE=false;talkNPC();}}
function attack(){if(!S.hasStarted||Date.now()<attackAt||$('#panel').classList.contains('open')||$('#dialog').classList.contains('open'))return;attackAt=Date.now()+450;let target=null,best=8;for(const e of enemies){let dx=e.mesh.position.x-player.x,dz=e.mesh.position.z-player.z,d=Math.hypot(dx,dz);let bearing=Math.atan2(dx,dz),delta=Math.atan2(Math.sin(bearing-player.yaw),Math.cos(bearing-player.yaw));if(d<best&&Math.abs(delta)<.9){target=e;best=d;}}sound('swing');if(target){let dmg=12+S.stats.Might*2+(S.weapon?.power||0)+Math.random()*5;target.hp-=dmg;target.mesh.scale.setScalar(1.13);setTimeout(()=>target.mesh.scale.setScalar(1),100);say('HIT · '+Math.floor(dmg));if(target.hp<=0)killEnemy(target);else if(!target.boss){$('#enemyName').textContent=target.name;$('#enemyFill').style.width=Math.max(0,100*target.hp/target.max)+'%';}if(target.boss)$('#bossFill').style.width=Math.max(0,100*target.hp/target.max)+'%';} }
function power(kind){if(Date.now()<powerAt||!S.hasStarted)return;powerAt=Date.now()+5000;if(kind==='arc'){if(S.mp<12){say('NOT ENOUGH FOCUS');return;}S.mp-=12;sound('magic');let hit=0;enemies.slice().forEach(e=>{if(Math.hypot(e.mesh.position.x-player.x,e.mesh.position.z-player.z)<6){e.hp-=32+S.stats.Insight*3;hit++;if(e.hp<=0)killEnemy(e);}});say(hit?'ARC NOVA · '+hit+' STRUCK':'ARC NOVA · NO TARGET');}else{if(S.mp<9){say('NOT ENOUGH FOCUS');return;}S.mp-=9;guardUntil=Date.now()+4500;say('AEGIS · 4.5 SECONDS');sound('magic');}updateUI();}
function usePotion(){if(S.potions<=0){say('NO POTIONS');return;}if(S.hp>=maxHP()){say('VITALITY ALREADY FULL');return;}S.potions--;S.hp=Math.min(maxHP(),S.hp+45);S.mp=Math.min(maxMP(),S.mp+15);sound('potion');say('POTION USED');updateUI();}
function killEnemy(e){scene.remove(e.mesh);enemies=enemies.filter(x=>x!==e);S.kills++;let reward=12+S.floor*2+(e.boss?60:0);S.xp+=reward;S.shards+=e.boss?45:5+Math.floor(Math.random()*8);S.log.unshift('Floor '+S.floor+': defeated '+e.name+' (+'+reward+' insight, +'+(e.boss?45:5)+' shards)');if(Math.random()<.38||e.boss)dropItem(e.boss);if(S.xp>=S.xpNext){S.xp-=S.xpNext;S.level++;S.xpNext=Math.floor(S.xpNext*1.25);S.points+=3;S.hp=maxHP();S.mp=maxMP();say('LEVEL UP · LEVEL '+S.level+' · 3 POINTS');}else say(e.boss?'GUARDIAN FALLEN · THE STAIRS UNSEAL':'FOE DEFEATED');if(enemies.length===0){if(S.floor===100){setTimeout(()=>ending(),600);}else if(S.floor%10===0)say('GUARDIAN FALLEN · THE STAIR IS OPEN');}updateUI();autosave();}
function dropItem(boss){let rarity=boss?'Legendary':rarities[Math.min(4,Math.floor(Math.random()*(S.difficulty==='hard'?4:3)))];let item={name:names[Math.floor(Math.random()*names.length)],rarity,type:Math.random()<.55?'weapon':Math.random()<.75?'armor':'relic',power:Math.ceil((S.floor+S.level)*(.12+rarities.indexOf(rarity)*.13)),floor:S.floor};if(item.type==='relic'){S.relics.push(item);say('RELIC FOUND · '+item.name);}else{S.log.unshift('Found '+rarity+' '+item.name);S.items=S.items||[];S.items.push(item);say(rarity.toUpperCase()+' · '+item.name+' FOUND');}}

