function maxHP(){return 100+S.stats.Vigor*8+(S.armor?.power||0)*2;}function maxMP(){return 60+S.stats.Insight*5;}function updateUI(){S.hp=Math.max(0,Math.min(maxHP(),S.hp));S.mp=Math.max(0,Math.min(maxMP(),S.mp));$('#floorTitle').textContent='Floor '+String(S.floor).padStart(2,'0')+' · '+floorName(S.floor);$('#namelevel').innerHTML=`${esc(S.name)} <span>LV ${S.level}</span>`;$('#hpFill').style.width=100*S.hp/maxHP()+'%';$('#hpText').textContent=Math.ceil(S.hp)+' / '+maxHP();$('#mpFill').style.width=100*S.mp/maxMP()+'%';$('#mpText').textContent=Math.ceil(S.mp)+' / '+maxMP();$('#xpFill').style.width=100*S.xp/S.xpNext+'%';$('#shards').textContent=S.shards;$('#points').textContent=S.points;$('#kills').textContent=S.kills;}
function floorName(n){if(n===1)return 'The Threshold';if(n===100)return 'The Last Dawn';return ['The Silt Archives','The Gilded Veil','The Drowned Choir','The Cinder Galleries','The Orchard Below'][Math.floor((n-1)/5)%5];}
function nextFloor(){S.floor++;S.hp=Math.min(maxHP(),S.hp+12);S.mp=Math.min(maxMP(),S.mp+10);buildFloor();updateUI();say('FLOOR '+S.floor+' · THE AIR CHANGES');autosave();if(S.floor===100)say('THE LAST DAWN AWAITS');}
function onDeath(){S.hp=Math.ceil(maxHP()*.35);S.mp=maxMP();S.shards=Math.floor(S.shards*.8);player.x=0;player.z=5;buildFloor();say('YOU WAKE AT THE LAST WAYSTONE · 20% SHARDS LOST');autosave();}
function talkNPC(){if(!npc)return;dialogNpc=npc;let favors=['I carry maps of places the tower has forgotten.','It listens when you tell the truth. Try that sometime.','The guardians are not keeping you out. They are keeping something in.','I have climbed this far by trading stories. Have you one?','A name is a promise. The tower collects on promises.'];$('#dialogEyebrow').textContent='FLOOR '+S.floor+' · '+npc.name;$('#dialogTitle').textContent=npc.name;$('#dialogText').textContent=favors[(S.floor/5-1)%favors.length]+' Their eyes flick toward your pack.';let choices=[];if(!npc.traded)choices.push(`<button class="btn choice" onclick="tradeNPC()">TRADE · 20 shards for a healing draught</button>`);choices.push(`<button class="btn secondary choice" onclick="askNPC()">ASK ABOUT THE TOWER</button>`);$('#dialogChoices').innerHTML=choices.join('');$('#dialog').classList.add('open');sound('open');}
function tradeNPC(){if(S.shards<20){$('#dialogText').textContent='“Even here, generosity cannot be bought with empty pockets.” You need 20 shards.';return;}S.shards-=20;S.potions++;dialogNpc.traded=true;$('#dialogText').textContent='“Take it. I have learned the hard way: no one climbs alone.” +1 healing draught.';$('#dialogChoices').innerHTML='<button class="btn secondary choice" onclick="closeDialog()">THANK YOU</button>';updateUI();autosave();sound('potion');}
function askNPC(){let lines=['Every tenth floor has a keeper. They carry the key to the next part of your story.','The marks on the walls are not numbers. They are names. Count them, if you dare.','Your relics are older than this tower. One day they may tell you why.','When the stairs glow, the floor has nothing left to ask of you.','I have seen the sun. It was not where we left it.'];$('#dialogText').textContent='“'+lines[Math.floor(Math.random()*lines.length)]+'”';$('#dialogChoices').innerHTML='<button class="btn secondary choice" onclick="talkNPC()">ASK SOMETHING ELSE</button>';sound('open');}
function ending(){ $('#dialogEyebrow').textContent='FLOOR 100 · THE LAST DAWN';$('#dialogTitle').textContent='The sun remembers your name.';$('#dialogText').textContent='The final keeper falls. Above you, the tower opens—not to a throne, but to morning. You have crossed one hundred floors, and every soul you met has left a mark in the light. The climb is yours to finish, or to begin again.';$('#dialogChoices').innerHTML='<button class="btn choice" onclick="S.floor=1;S.hp=maxHP();buildFloor();updateUI();closeDialog();say(\'A NEW CLIMB BEGINS\')">BEGIN A NEW ASCENT</button>';$('#dialog').classList.add('open');}
function startGame(){S.name=$('#heroName').value.trim()||'Wayfarer';S.difficulty=$('#difficulty').value;S.hasStarted=true;$('#welcome').classList.remove('open');init3d();updateUI();autosave();say('THE CLIMB BEGINS · FLOOR 1');}
function say(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100);}
function openPanel(tab){if(!S.hasStarted)return;$('#panel').classList.add('open');showTab(tab);sound('open');}
function closePanel(){ $('#panel').classList.remove('open');}
function showTab(tab){document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===tab));$('#panelTitle').textContent=({character:'Character',inventory:'Equipment & relics',journal:'Tower journal',settings:'Options'})[tab];$('#panelEyebrow').textContent=(S.name+' · FLOOR '+S.floor).toUpperCase();let c=$('#panelContent');
if(tab==='character'){c.innerHTML=`<div class="row between"><p>Level ${S.level} · ${S.xp}/${S.xpNext} insight<br>Distribute <b style="color:var(--gold)">${S.points}</b> attribute points</p><p style="text-align:right">Difficulty<br><b>${S.difficulty.toUpperCase()}</b></p></div><div class="grid">${Object.entries(S.stats).map(([k,v])=>`<div class="tile"><div class="row between"><strong>${k}</strong><button onclick="addPoint('${k}')" ${S.points?'':'disabled'}>+</button></div><p>${({Might:'Weapon damage',Vigor:'Maximum vitality',Insight:'Focus & power',Agility:'Move speed'})[k]} · <b>${v}</b></p></div>`).join('')}</div><div class="tile" style="margin-top:10px"><strong>Active gear</strong><p>Weapon: ${S.weapon?S.weapon.name+' (+'+S.weapon.power+')':'Unarmed'} · Armor: ${S.armor?S.armor.name+' (+'+S.armor.power+')':'Traveler’s clothes'}</p><p>Relics: ${S.relics.length} · Potions: ${S.potions}</p></div>`;}
if(tab==='inventory'){let all=[...(S.items||[]),...S.relics];c.innerHTML=`<div class="row between"><p>Equipment improves your chances. The tower's treasures are never quite the same.</p><span class="startmark">${S.shards} SHARDS</span></div><h3 style="font-size:11px;color:#aab3b2">BACKPACK · CLICK TO EQUIP</h3><div class="inventory">${all.length?all.map((it,i)=>`<div class="item" onclick="equipItem(${i})"><strong class="${rarityClass(it.rarity)}">${it.name}</strong><small>${it.rarity} ${it.type} · +${it.power} ${it.type==='weapon'?'damage':it.type==='armor'?'guard':'power'}</small>${it.type==='relic'?'<small>Relic · passive vitality +12</small>':''}</div>`).join(''):'<p>Your pack is quiet. Defeat enemies and guardians to find gear.</p>'}</div><div class="row between" style="margin-top:14px"><span class="startmark">HEALING DRAUGHTS · ${S.potions}</span><button class="btn secondary small" onclick="usePotion()">USE POTION (F)</button></div>`;}

