function sound(type){if(S.sound===false)return;try{let ctx=window.ac||(window.ac=new AudioContext()),o=ctx.createOscillator(),g=ctx.createGain(),now=ctx.currentTime;o.connect(g);g.connect(ctx.destination);let f={swing:180,hit:90,hurt:65,magic:540,potion:660,open:420}[type]||300;o.type=type==='hurt'?'sawtooth':'sine';o.frequency.setValueAtTime(f,now);o.frequency.exponentialRampToValueAtTime(f*.55,now+.12);g.gain.setValueAtTime(.035,now);g.gain.exponentialRampToValueAtTime(.001,now+.16);o.start(now);o.stop(now+.17);}catch(e){}}
// Inline UI hooks are intentionally explicit: the rest of the game remains module-scoped.
Object.assign(window,{startGame,openPanel,closePanel,showTab,closeDialog,tradeNPC,askNPC,addPoint,equipItem,usePotion,setLang,resetGame});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space')attack();if(e.code==='KeyQ')power('arc');if(e.code==='KeyE'&&npc&&Math.hypot(player.x-npc.mesh.position.x,player.z-npc.mesh.position.z)<3)talkNPC();if(e.code==='KeyF')usePotion();if(e.code==='Escape'){closePanel();closeDialog();}});window.addEventListener('keyup',e=>keys[e.code]=false);
let dragging=false,lastX=0,lastY=0;document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer?.domElement){player.yaw-=e.movementX*.0022;player.pitch=Math.max(-1.25,Math.min(1.25,player.pitch-e.movementY*.0018));}else if(dragging){player.yaw-=(e.clientX-lastX)*.004;player.pitch=Math.max(-1.2,Math.min(1.2,player.pitch-(e.clientY-lastY)*.003));lastX=e.clientX;lastY=e.clientY;}});document.addEventListener('mousedown',e=>{if(e.target===renderer?.domElement){dragging=true;lastX=e.clientX;lastY=e.clientY;}});document.addEventListener('mouseup',()=>dragging=false);
$('#scene').addEventListener('click',e=>{if(!S.hasStarted)return;if(document.pointerLockElement!==renderer.domElement&&innerWidth>700){renderer.domElement.requestPointerLock?.();}attack();});$('#attackTouch').addEventListener('pointerdown',e=>{e.preventDefault();attack();});$('#powerTouch').addEventListener('pointerdown',e=>{e.preventDefault();power('arc');});$('#guardTouch').addEventListener('pointerdown',e=>{e.preventDefault();power('guard');});
$('#joystick').addEventListener('pointerdown',e=>{e.preventDefault();$('#joystick').setPointerCapture(e.pointerId);joystickMove(e);});$('#joystick').addEventListener('pointermove',e=>{if(e.buttons)joystickMove(e);});$('#joystick').addEventListener('pointerup',()=>{moveTouch={x:0,y:0};$('#stick').style.transform='translate(0,0)';});function joystickMove(e){let r=$('#joystick').getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy),k=Math.min(1,32/(d||1));moveTouch={x:dx*k/32,y:dy*k/32};$('#stick').style.transform=`translate(${dx*k}px,${dy*k}px)`;}
$('#panel').addEventListener('click',e=>{if(e.target===$('#panel'))closePanel();});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))closeDialog();});window.addEventListener('resize',()=>{if(renderer){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);}});
loadSave();if(S.lang==='es')setLang('es');
</script></body></html>

